insert into momentos.me_conta_cards (slug, age_band, level, question, tip) values
('24-lev-bicho', '2-4'::momentos.age_band, 'leve', 'Se o seu travesseiro fosse um bicho, qual seria?', 'Você começa. Faça o som do bicho que escolheu.'),
